head.script:
// 담당 범위 : maskFormatModelExcludeChar 가이드 전 항목 (con_maskFormatModelExcludeChar 1개, 검증 Column 7개를 한 화면에서 비교)
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
//  - 적용 전제(inputType=text, embeddedInput=false, maskFormat, displayFormat)는 전제를 하나씩 뺀 대조 Column 으로 확인 (옵션 0 에서 저장값의 0 제거 여부로 판별)



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > maskFormatModelExcludeChar]<br/>Cell 편집을 완료할 때 DataList 에 저장되는 값에서 제거할 문자를 설정합니다.",
    "validation" : [
        "Column 의 inputType='text', embeddedInput='false' 이고 maskFormat, displayFormat 속성이 설정된 경우에 동작합니다.",
        "문자열 설정 시, Cell 의 입력값에서 제거할 문자를 구분자 없이 이어서 설정합니다.",
        "문자열 설정 시, ex- '()-' 로 설정하면 '(', ')', '-' 문자가 저장값에서 모두 제거됩니다.",
        "maskFormat 속성을 설정하면 Cell 표시값이 그대로 DataList 에 저장되므로, 저장값에서 빼야 하는 문자를 이 속성으로 설정합니다.",
        "사용자가 화면에서 Cell 을 편집한 경우에만 적용되며 메소드로 데이터를 설정한 경우에는 적용되지 않습니다.",
        "maskFormatModelExcludeChar 속성으로 제거된 값은 DataList 에만 반영되며, 화면에는 displayFormat 속성이 적용된 값이 표시됩니다."
    ]
}



scwin.gVar = {
    // 편집 중 키를 뗄 때마다 기록한 입력창 값 (셀 더블클릭 시 초기화)
    "editValue" : []
};

// 검증 Column 정보 (id / 출력 라벨 / Header 표시값)
scwin.colInfo = [
    { "id" : "txt",       "label" : "text (###)###-####",            "header" : "text" },
    { "id" : "numTel",    "label" : "number (###)###-####",          "header" : "number (###)" },
    { "id" : "num",       "label" : "number #,###",                  "header" : "number #,###" },
    { "id" : "txtEmb",    "label" : "text embeddedInput=true",       "header" : "embeddedInput" },
    { "id" : "txtNoMask", "label" : "text maskFormat 미설정",        "header" : "maskFormat 없음" },
    { "id" : "txtNoFmt",  "label" : "text displayFormat 미설정",     "header" : "displayFormat 없음" },
    { "id" : "txtArea",   "label" : "textarea (###)###-####",        "header" : "textarea" }
];



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (가이드 예시 '()-')
    con_maskFormatModelExcludeChar.setValue("()-");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 검증 Column 7개 모두 con_maskFormatModelExcludeChar 값을 같은 값으로 설정한다 (미설정은 속성 자체를 넣지 않는다)
//  - txt / numTel / num : 전제(inputType=text, embeddedInput 미설정(false), maskFormat=default, displayFormat)를 모두 충족
//  - txtEmb / txtNoMask / txtNoFmt / txtArea : txt 에서 전제를 하나씩 뺀 대조 Column (embeddedInput=true / maskFormat 미설정 / displayFormat 미설정 / inputType=textarea)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.editValue = [];

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 모든 검증 Column 에 maskFormatModelExcludeChar 를 옵션값으로 함께 설정 (Column 별 전제 구성은 결과창 출력 라벨 참고)\n[절차] 옵션 선택 -> Target 재생성 -> 결과창 clear -> 셀 더블클릭(embeddedInput Column 은 셀 입력창 클릭) -> 입력값을 지우고 0298765432 를 한 자씩 입력 -> 결과창 클릭으로 편집 종료\n[확인] 편집 종료 시 셀 표시값 / DataList 저장값 자동 출력, setCellData 버튼은 메소드로 설정한 Row 0 의 DataList 값 / 셀 표시값 출력"', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue, 미설정은 속성 자체를 넣지 않는다)
    let cExcludeChar = con_maskFormatModelExcludeChar.getValue();
    let attrExclude = '';
    if (cExcludeChar !== '') {
        attrExclude = ' maskFormatModelExcludeChar="' + cExcludeChar + '"';
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (body column id 와 동일한 컬럼 id 사용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="txt" name="txt" dataType="text"></w2:column>';
    strDlt += '<w2:column id="numTel" name="numTel" dataType="number"></w2:column>';
    strDlt += '<w2:column id="num" name="num" dataType="number"></w2:column>';
    strDlt += '<w2:column id="txtEmb" name="txtEmb" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtNoMask" name="txtNoMask" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtNoFmt" name="txtNoFmt" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtArea" name="txtArea" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "txt" : "0311234567", "numTel" : "0311234567", "num" : "3456", "txtEmb" : "0311234567", "txtNoMask" : "0311234567", "txtNoFmt" : "0311234567", "txtArea" : "0311234567" },
        { "txt" : "0215550123", "numTel" : "0215550123", "num" : "5678", "txtEmb" : "0215550123", "txtNoMask" : "0215550123", "txtNoFmt" : "0215550123", "txtArea" : "0215550123" }
    ], false);

    // 이벤트 바인딩 (편집 종료 시 저장값 출력)
    let eList = $c.gcm.createEList(["onviewchange"]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" defaultCellHeight="30" id="" style="width:910px;height:120px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    for (let i = 0; i < scwin.colInfo.length; i++) {
        strTarget += '<w2:column width="130" style="" inputType="text" id="column' + (i + 1) + '" value="' + scwin.colInfo[i].header + '"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" id="txt" value="" inputType="text" dataType="text" displayFormat="(###)###-####" maskFormat="default"' + attrExclude + '></w2:column>';
    strTarget += '<w2:column width="130" style="" id="numTel" value="" inputType="text" dataType="number" displayFormat="(###)###-####" maskFormat="default"' + attrExclude + '></w2:column>';
    strTarget += '<w2:column width="130" style="" id="num" value="" inputType="text" dataType="number" displayFormat="#,###" maskFormat="default"' + attrExclude + '></w2:column>';
    strTarget += '<w2:column width="130" style="" id="txtEmb" value="" inputType="text" dataType="text" displayFormat="(###)###-####" maskFormat="default" embeddedInput="true"' + attrExclude + '></w2:column>';
    strTarget += '<w2:column width="130" style="" id="txtNoMask" value="" inputType="text" dataType="text" displayFormat="(###)###-####"' + attrExclude + '></w2:column>';
    strTarget += '<w2:column width="130" style="" id="txtNoFmt" value="" inputType="text" dataType="text" maskFormat="default"' + attrExclude + '></w2:column>';
    strTarget += '<w2:column width="130" style="" id="txtArea" value="" inputType="textarea" dataType="text" displayFormat="(###)###-####" maskFormat="default"' + attrExclude + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 편집 입력창 값 기록 (셀 더블클릭(편집 진입) / 내장 입력창 클릭 시 기록 초기화)
    target1.render.addEventListener("dblclick", function () {
        scwin.gVar.editValue = [];
    }, true);
    target1.render.addEventListener("mousedown", function (e) {
        if (e.target && e.target.tagName === "INPUT") {
            scwin.gVar.editValue = [];
        }
    }, true);
    target1.render.addEventListener("keyup", scwin.recordEditValue, true);

    // 옵션 적용값 출력
    wf_body_bottom.getObj("scwin").setReturnValue("maskFormatModelExcludeChar : " + (cExcludeChar === '' ? "(미설정)" : cExcludeChar));
}



// 셀 표시값 (maskFormat + displayFormat Column 은 getCellDisplayData 가 값을 반환하지 않아 화면 Cell 의 텍스트를 읽는다, 내장 입력창은 입력창 값)
scwin.getCellText = function (rowIndex, colIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_" + colIndex + "']");
    if (!td) {
        return "";
    }
    let input = td.querySelector("input");
    return input ? input.value : td.textContent;
}



// 편집 중 키를 뗄 때마다 입력창 값을 기록 (입력창의 포맷 처리가 끝난 뒤의 값을 읽는다)
scwin.recordEditValue = function (e) {
    let elem = e.target;
    if (!elem || (elem.tagName !== "INPUT" && elem.tagName !== "TEXTAREA")) {
        return;
    }
    setTimeout(function () {
        let arr = scwin.gVar.editValue;
        if (arr.length === 0 || arr[arr.length - 1] !== elem.value) {
            arr.push(elem.value);
        }
    }, 0);
}



// validation 1 ~ 4, 6 판정 출력 : 편집 중 입력창 값 / 편집 종료 후 셀 표시값 / DataList 저장값
scwin.target1_onviewchange = function (info) {
    let colId = target1.getColumnID(info.colIndex);
    let arr = scwin.gVar.editValue;
    wf_body_bottom.getObj("scwin").setReturnValue("Row " + info.rowIndex + " / " + scwin.colInfo[info.colIndex].label
        + " 편집 중 입력창 값 : " + (arr.length > 0 ? arr[arr.length - 1] : "")
        + " -> 셀 표시값 : " + scwin.getCellText(info.rowIndex, info.colIndex)
        + " / DataList 저장값 : " + dlt_bind.getCellData(info.rowIndex, colId));
}



// validation 5 판정 출력 : DataList setCellData 메소드로 제거 대상 문자가 든 값을 설정한 뒤 DataList 값 / 셀 표시값
scwin.btn_setCellData_onclick = function (e) {
    dlt_bind.setCellData(0, "numTel", "(031)123-4567");
    dlt_bind.setCellData(0, "num", "1,234");
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("setCellData Row 0 / " + scwin.colInfo[1].label + " : (031)123-4567 -> DataList 값 : " + dlt_bind.getCellData(0, "numTel") + " / 셀 표시값 : " + scwin.getCellText(0, 1));
    bottom.setReturnValue("setCellData Row 0 / " + scwin.colInfo[2].label + " : 1,234 -> DataList 값 : " + dlt_bind.getCellData(0, "num") + " / 셀 표시값 : " + scwin.getCellText(0, 2));
};
